import{c as t,Q as a,j as n,m as e}from"./chunks/framework.DOi4mjdC.js";const l="/assets/zh-cn_image_0000001487548198.zFxNrLCp.png",p="/assets/zh-cn_image_0000001538108293.DEM9tmYp.png",m=JSON.parse('{"title":"MrgSort","description":"","frontmatter":{},"headers":[{"level":1,"title":"MrgSort","slug":"mrgsort"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/高阶API/排序操作/MrgSort-93.md","filePath":"api/SIMD-API/高阶API/排序操作/MrgSort-93.md"}'),i={name:"api/SIMD-API/高阶API/排序操作/MrgSort-93.md"};function r(o,s,d,c,u,h){return a(),n("div",null,[...s[0]||(s[0]=[e('<h1 id="mrgsort" tabindex="-1">MrgSort <a class="header-anchor" href="#mrgsort" aria-label="Permalink to &quot;MrgSort&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>√</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>√</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>x</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>√</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>将已经排好序的最多4条队列，合并排列成1条队列，结果按照score域由大到小排序，排布方式如下：</p><p>Ascend 950PR/Ascend 950DT采用方式一。</p><p>Atlas A3 训练系列产品/Atlas A3 推理系列产品采用方式一。</p><p>Atlas A2 训练系列产品/Atlas A2 推理系列产品采用方式一。</p><p>Atlas 推理系列产品AI Core采用方式二。</p><ul><li><p>排布方式一：</p><p>MrgSort处理的数据一般是经过Sort处理后的数据，也就是Sort接口的输出，队列的结构如下所示：</p><ul><li><p>数据类型为float，每个结构占据8Bytes。</p><p><img src="'+l+'" alt=""></p></li><li><p>数据类型为half，每个结构也占据8Bytes，中间有2Bytes保留。</p><p><img src="'+p+`" alt=""></p></li></ul></li><li><p>排布方式二：Region Proposal排布</p><p>输入输出数据均为Region Proposal，具体请参见<a href="./Sort.html">Sort</a>中的排布方式二。</p></li></ul><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T, bool isExhaustedSuspension = false&gt;</span></span>
<span class="line"><span>__aicore__ inline void MrgSort(const LocalTensor&lt;T&gt; &amp;dst, const MrgSortSrcList&lt;T&gt; &amp;sortList, const uint16_t elementCountList[4], uint32_t sortedNum[4], uint16_t validBit, const int32_t repeatTime)</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 模板参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>T</td><td>操作数的数据类型。支持的数据类型为：half、float。</td></tr><tr><td>isExhaustedSuspension</td><td>某条队列耗尽（即该队列已经全部排序到目的操作数）后，是否需要停止合并。类型为bool，参数取值如下： false：直到所有队列耗尽完才停止合并。true：某条队列耗尽后，停止合并。 默认值为false。</td></tr></tbody></table><p><strong>表 2</strong> 接口参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>dst</td><td>输出</td><td>目的操作数，存储经过排序后的数据。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。</td></tr><tr><td>sortList</td><td>输入</td><td>源操作数，支持2-4个队列，并且每个队列都已经排好序，类型为MrgSortSrcList结构体，具体请参考表3。MrgSortSrcList中传入要合并的队列。 &lt;pre class=&quot;screen&quot; codetype=&quot;Cpp&quot; id=&quot;screen92612599281&quot;&gt;template &lt;typename T&gt; struct MrgSortSrcList { LocalTensor&lt;T&gt; src1; LocalTensor&lt;T&gt; src2; LocalTensor&lt;T&gt; src3; // 当要合并的队列个数小于3，可以为空tensor LocalTensor&lt;T&gt; src4; // 当要合并的队列个数小于4，可以为空tensor };&lt;/pre&gt;</td></tr><tr><td>elementCountList</td><td>输入</td><td>四个源队列的长度（排序方式一：8Bytes结构的数目，排序方式二：16*sizeof(T)Bytes结构的数目），类型为长度为4的uint16_t数据类型的数组，理论上每个元素取值范围[0, 4095]，但不能超出UB的存储空间。</td></tr><tr><td>sortedNum</td><td>输出</td><td>耗尽模式下（即isExhaustedSuspension为true时），停止合并时每个队列已排序的元素个数。</td></tr><tr><td>validBit</td><td>输入</td><td>有效队列个数，取值如下：0b11：前两条队列有效0b111：前三条队列有效0b1111：四条队列全部有效</td></tr><tr><td>repeatTime</td><td>输入</td><td>迭代次数，每一次源操作数和目的操作数跳过四个队列总长度。取值范围：repeatTime∈[1,255]。 repeatTime参数生效是有条件的，需要同时满足以下四个条件：srcLocal包含四条队列并且validBit=15四个源队列的长度一致四个源队列连续存储isExhaustedSuspension为false</td></tr></tbody></table><p><strong>表 3</strong> MrgSortSrcList参数说明</p><table tabindex="0"><thead><tr><th>参数名称</th><th>输入/输出</th><th>含义</th></tr></thead><tbody><tr><td>src1</td><td>输入</td><td>源操作数，第一个已经排好序的队列。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。 数据类型与目的操作数保持一致。支持的数据类型为：half、float。</td></tr><tr><td>src2</td><td>输入</td><td>源操作数，第二个已经排好序的队列。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。 数据类型与目的操作数保持一致。支持的数据类型为：half、float。</td></tr><tr><td>src3</td><td>输入</td><td>源操作数，第三个已经排好序的队列。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。 数据类型与目的操作数保持一致。支持的数据类型为：half、float。</td></tr><tr><td>src4</td><td>输入</td><td>源操作数，第四个已经排好序的队列。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。 数据类型与目的操作数保持一致。支持的数据类型为：half、float。</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li>当存在score[i]与score[j]相同时，如果i&gt;j，则score[j]将首先被选出来，排在前面，即index的顺序与输入顺序一致。</li><li>每次迭代内的数据会进行排序，不同迭代间的数据不会进行排序。</li><li>操作数地址对齐要求请参见<a href="./../../通用说明和约束.html#section796754519912">通用地址对齐约束</a>。</li></ul><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><ul><li><p>处理128个half类型数据。</p><p>该样例适用于：</p><p>Ascend 950PR/Ascend 950DT</p><p>Atlas A2 训练系列产品/Atlas A2 推理系列产品</p><p>Atlas A3 训练系列产品/Atlas A3 推理系列产品</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>uint32_t elementCount = 128; // 元素个数</span></span>
<span class="line"><span>uint32_t calcBufferSize = elementCount * 8; // 每个元素占据8字节</span></span>
<span class="line"><span>uint32_t tmpBufferSize = elementCount * 8;</span></span>
<span class="line"><span>uint32_t sortedLocalSize = elementCount * 4; </span></span>
<span class="line"><span>uint32_t sortRepeatTimes = elementCount / 32;</span></span>
<span class="line"><span>uint32_t extractRepeatTimes = elementCount / 32;</span></span>
<span class="line"><span>uint32_t sortTmpLocalSize = elementCount * 4;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>uint32_t singleMergeTmpElementCount = elementCount / 4;</span></span>
<span class="line"><span>uint32_t baseOffset = AscendC::GetSortOffset&lt;half&gt;(singleMergeTmpElementCount);</span></span>
<span class="line"><span>AscendC::MrgSortSrcList sortList = AscendC::MrgSortSrcList(sortedLocal[0], sortedLocal[baseOffset], sortedLocal[2 * baseOffset], sortedLocal[3 * baseOffset]); // sortList：待合并的有序队列列表</span></span>
<span class="line"><span>uint16_t singleDataSize = elementCount / 4; // 队列长度</span></span>
<span class="line"><span>const uint16_t elementCountList[4] = {singleDataSize, singleDataSize, singleDataSize, singleDataSize}; // 4个队列的长度</span></span>
<span class="line"><span>uint32_t sortedNum[4];</span></span>
<span class="line"><span>// 合并sortList中的4条队列</span></span>
<span class="line"><span>AscendC::MrgSort&lt;half, false&gt;(sortTmpLocal, sortList, elementCountList, sortedNum, 0b1111, 1);</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>示例结果</span></span>
<span class="line"><span>输入数据(srcValueGm): 128个half类型数据</span></span>
<span class="line"><span>[31 30 29 ... 2 1 0</span></span>
<span class="line"><span> 63 62 61 ... 34 33 32</span></span>
<span class="line"><span> 95 94 93 ... 66 65 64</span></span>
<span class="line"><span> 127 126 125 ... 98 97 96]</span></span>
<span class="line"><span>输入数据(srcIndexGm):</span></span>
<span class="line"><span>[31 30 29 ... 2 1 0</span></span>
<span class="line"><span> 63 62 61 ... 34 33 32</span></span>
<span class="line"><span> 95 94 93 ... 66 65 64</span></span>
<span class="line"><span> 127 126 125 ... 98 97 96]</span></span>
<span class="line"><span>输出数据(dstValueGm):</span></span>
<span class="line"><span>[127 126 125 ... 2 1 0]</span></span>
<span class="line"><span>输出数据(dstIndexGm):</span></span>
<span class="line"><span>[127 126 125 ... 2 1 0]</span></span></code></pre></div></li><li><p>处理64个half类型数据。</p><p>该样例适用于：</p><p>Atlas 推理系列产品AI Core</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>uint32_t elementCount = 64; // 元素个数</span></span>
<span class="line"><span>// 单条队列元素个数</span></span>
<span class="line"><span>uint32_t singleMergeTmpElementCount = elementCount / 4;</span></span>
<span class="line"><span>uint32_t baseOffset = AscendC::GetSortOffset&lt;half&gt;(singleMergeTmpElementCount);</span></span>
<span class="line"><span>AscendC::MrgSortSrcList sortList = AscendC::MrgSortSrcList(sortedLocal[0], sortedLocal[baseOffset], sortedLocal[2 * baseOffset], sortedLocal[3 * baseOffset]); // sortList：待合并的有序队列列表</span></span>
<span class="line"><span>uint16_t singleDataSize = elementCount / 4; // 队列长度</span></span>
<span class="line"><span>const uint16_t elementCountList[4] = {singleDataSize, singleDataSize, singleDataSize, singleDataSize}; // 4个队列的长度</span></span>
<span class="line"><span>uint32_t sortedNum[4];</span></span>
<span class="line"><span>// 合并sortList中的4条队列</span></span>
<span class="line"><span>AscendC::MrgSort&lt;half, false&gt;(sortTmpLocal, sortList, elementCountList, sortedNum, 0b1111, 1);</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>示例结果</span></span>
<span class="line"><span>输入数据(srcValueGm): 64个half类型数据</span></span>
<span class="line"><span>[15 14 13 ... 2 1 0</span></span>
<span class="line"><span> 31 30 29 ... 18 17 16</span></span>
<span class="line"><span> 47 46 45 ... 34 33 32</span></span>
<span class="line"><span> 63 62 61 ... 50 49 48]</span></span>
<span class="line"><span>输入数据(srcIndexGm):</span></span>
<span class="line"><span>[15 14 13 ... 2 1 0</span></span>
<span class="line"><span> 31 30 29 ... 18 17 16</span></span>
<span class="line"><span> 47 46 45 ... 34 33 32</span></span>
<span class="line"><span> 63 62 61 ... 50 49 48]</span></span>
<span class="line"><span>输出数据(dstValueGm):</span></span>
<span class="line"><span>[63 62 61 ... 2 1 0]</span></span>
<span class="line"><span>输出数据(dstIndexGm):</span></span>
<span class="line"><span>[63 62 61 ... 2 1 0]</span></span></code></pre></div></li></ul>`,25)])])}const b=t(i,[["render",r]]);export{m as __pageData,b as default};
